<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class WelcomeSlide extends Model { protected $guarded=[]; protected function casts():array{return ['is_active'=>'boolean'];} public function getImageUrlAttribute(): string { return str_starts_with((string) $this->image_path, 'assets/') || str_starts_with((string) $this->image_path, 'storage/') ? asset($this->image_path) : asset('storage/'.$this->image_path); } }
